function f(a: number = 1, g: () => number = () => a): number { a = 2; return g(); }
function mk(x: number = 0, inc: () => number = () => ++x): () => number { return inc; }
async function main(): Promise<void> {
  console.log(f());
  console.log(f(5));
  const i1 = mk();
  const i2 = mk();
  console.log(i1(), i1(), i2());
  console.log(mk(10)());
}
